00069 class AdaptiveLoopFilter
00070 {
00071 public:
00072   static inline Pel clipALF(const Pel clip, const Pel ref, const Pel val0, const Pel val1)
00073   {
00074     return Clip3<Pel>(-clip, +clip, val0-ref) + Clip3<Pel>(-clip, +clip, val1-ref);
00075   }
00076 
00077   static constexpr int AlfNumClippingValues[MAX_NUM_CHANNEL_TYPE] = { 4, 4 };
00078   static constexpr int MaxAlfNumClippingValues = 4;
00079 
00080   static constexpr int   m_NUM_BITS = 8;
00081   static constexpr int   m_CLASSIFICATION_BLK_SIZE = 32;  //non-normative, local buffer size
00082   static constexpr int m_ALF_UNUSED_CLASSIDX = 255;
00083   static constexpr int m_ALF_UNUSED_TRANSPOSIDX = 255;
00084 
00085   AdaptiveLoopFilter();
00086   virtual ~AdaptiveLoopFilter() {}
00087   void reconstructCoeffAPSs(CodingStructure& cs, bool luma, bool chroma, bool isRdo);
00088   void reconstructCoeff(AlfParam& alfParam, ChannelType channel, const bool isRdo, const bool isRedo = false);
00089   void ALFProcess(CodingStructure& cs);
00090   void create( const int picWidth, const int picHeight, const ChromaFormat format, const int maxCUWidth, const int maxCUHeight, const int maxCUDepth, const int inputBitDepth[MAX_NUM_CHANNEL_TYPE] );
00091   void destroy();
00092   static void deriveClassificationBlk(AlfClassifier **classifier, int **laplacian[NUM_DIRECTIONS],
00093                                       const CPelBuf &srcLuma, const Area &blkDst, const Area &blk, const int shift,
00094                                       const int vbCTUHeight, int vbPos);
00095   void deriveClassification( AlfClassifier** classifier, const CPelBuf& srcLuma, const Area& blkDst, const Area& blk );
00096   template<AlfFilterType filtTypeCcAlf>
00097   static void filterBlkCcAlf(const PelBuf &dstBuf, const CPelUnitBuf &recSrc, const Area &blkDst, const Area &blkSrc,
00098                              const ComponentID compId, const int16_t *filterCoeff, const ClpRngs &clpRngs,
00099                              CodingStructure &cs, int vbCTUHeight, int vbPos);
00100 
00101   template<AlfFilterType filtType>
00102   static void filterBlk(AlfClassifier **classifier, const PelUnitBuf &recDst, const CPelUnitBuf &recSrc,
00103                         const Area &blkDst, const Area &blk, const ComponentID compId, const short *filterSet,
00104                        const Pel *fClipSet, const ClpRng &clpRng, CodingStructure &cs, const int vbCTUHeight,
00105                        int vbPos);
00106   void (*m_deriveClassificationBlk)(AlfClassifier **classifier, int **laplacian[NUM_DIRECTIONS], const CPelBuf &srcLuma,
00107                                     const Area &blkDst, const Area &blk, const int shift, const int vbCTUHeight,
00108                                     int vbPos);
00109 
00110   void (*m_filterCcAlf)(const PelBuf &dstBuf, const CPelUnitBuf &recSrc, const Area &blkDst, const Area &blkSrc,
00111                         const ComponentID compId, const int16_t *filterCoeff, const ClpRngs &clpRngs,
00112                         CodingStructure &cs, int vbCTUHeight, int vbPos);
00113   void applyCcAlfFilter(CodingStructure &cs, ComponentID compID, const PelBuf &dstBuf, const PelUnitBuf &recYuvExt,
00114                         uint8_t *   filterControl,
00115                         const short filterSet[MAX_NUM_CC_ALF_FILTERS][MAX_NUM_CC_ALF_CHROMA_COEFF],
00116                         const int   selectedFilterIdx);
00117   CcAlfFilterParam &getCcAlfFilterParam() { return m_ccAlfFilterParam; }
00118   uint8_t* getCcAlfControlIdc(const ComponentID compID)   { return m_ccAlfFilterControl[compID-1]; }
00119   void (*m_filter5x5Blk)(AlfClassifier **classifier, const PelUnitBuf &recDst, const CPelUnitBuf &recSrc,
00120                          const Area &blkDst, const Area &blk, const ComponentID compId, const short *filterSet,
00121                          const Pel *fClipSet, const ClpRng &clpRng, CodingStructure &cs, const int vbCTUHeight,
00122                          int vbPos);
00123   void (*m_filter7x7Blk)(AlfClassifier **classifier, const PelUnitBuf &recDst, const CPelUnitBuf &recSrc,
00124                          const Area &blkDst, const Area &blk, const ComponentID compId, const short *filterSet,
00125                          const Pel *fClipSet, const ClpRng &clpRng, CodingStructure &cs, const int vbCTUHeight,
00126                          int vbPos);
00127 
00128 #ifdef TARGET_SIMD_X86
00129   void initAdaptiveLoopFilterX86();
00130   template <X86_VEXT vext>
00131   void _initAdaptiveLoopFilterX86();
00132 #endif
