00157   int m_laplacianData[NUM_DIRECTIONS][m_CLASSIFICATION_BLK_SIZE + 5][m_CLASSIFICATION_BLK_SIZE + 5];
00158   uint8_t*                     m_ctuEnableFlag[MAX_NUM_COMPONENT];
