00162   int                          m_inputBitDepth[MAX_NUM_CHANNEL_TYPE];
00163   int                          m_picWidth;
00164   int                          m_picHeight;
00165   int                          m_maxCUWidth;
00166   int                          m_maxCUHeight;
00167   int                          m_maxCUDepth;
00168   int                          m_numCTUsInWidth;
00169   int                          m_numCTUsInHeight;
00170   int                          m_numCTUsInPic;
00171   int                          m_alfVBLumaPos;
00172   int                          m_alfVBChmaPos;
00173   int                          m_alfVBLumaCTUHeight;
00174   int                          m_alfVBChmaCTUHeight;
00175   ChromaFormat                 m_chromaFormat;
00176   ClpRngs                      m_clpRngs;
00177 };
